def transform(grid):
    colors = {v for row in grid for v in row if v != 0}
    objects = []

    for color in colors:
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        shape = [
            [color if grid[r][c] == color else 0 for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)
        ]
        objects.append((c0, shape))

    objects.sort(key=lambda item: item[0])
    height = max(len(shape) for _, shape in objects)
    width = sum(len(shape[0]) for _, shape in objects)
    out = [[0] * width for _ in range(height)]

    c0 = 0
    for _, shape in objects:
        h, w = len(shape), len(shape[0])
        r0 = (height - h) // 2
        for r in range(h):
            for c in range(w):
                out[r0 + r][c0 + c] = shape[r][c]
        c0 += w

    return out
